Here is the commit message:
fbcon: Avoid OOB font access if console rotation fails

Clear the font buffer if the reallocation during console rotation fails
in fbcon_rotate_font(). The putcs implementations for the rotated buffer
will return early in this case. See [1] for an example.

Currently, fbcon_rotate_font() keeps the old buffer, which is too small
for the rotated font. Printing to the rotated console with a high-enough
character code will overflow the font buffer.

v2:
- fix typos in commit message

Signed-off-by: Thomas Zimmermann <tzimmermann@suse.de>
Fixes: 6cc50e1c5b57 ("[PATCH] fbcon: Console Rotation - Add support to rotate font bitmap")
Cc: stable@vger.kernel.org # v2.6.15+
Link: https://elixir.bootlin.com/linux/v6.19/source/drivers/video/fbdev/core/fbcon_ccw.c#L144 # [1]
Signed-off-by: Helge Deller <deller@gmx.de>

Here is the root cause:
In `fbcon_rotate_font()`, when reallocating the font buffer with `kmalloc_array` fails, the old (insufficiently sized) font buffer is retained without updating its size. This causes subsequent rotated text output operations (e.g., in `fbcon_ccw.c`) to access beyond the allocated buffer when handling high character codes, leading to an out-of-bounds read/write. The fix ensures that on allocation failure, the old buffer is freed and the pointer is set to NULL, causing the `putcs` implementations to abort early.

Here is the patch:

 int fbcon_rotate_font(struct fb_info *info, struct vc_data *vc)
 {
 	struct fbcon_par *par = info->fbcon_par;
 	int len, err = 0;
 	int s_cellsize, d_cellsize, i;
 	const u8 *src;
 	u8 *dst;

 	if (vc->vc_font.data == par->fontdata &&
 	    par->p->con_rotate == par->cur_rotate)
 		goto finished;

 	src = par->fontdata = vc->vc_font.data;
 	par->cur_rotate = par->p->con_rotate;
 	len = vc->vc_font.charcount;
 	s_cellsize = ((vc->vc_font.width + 7)/8) *
 		vc->vc_font.height;
 	d_cellsize = s_cellsize;

 	if (par->rotate == FB_ROTATE_CW ||
 	    par->rotate == FB_ROTATE_CCW)
 		d_cellsize = ((vc->vc_font.height + 7)/8) *
 			vc->vc_font.width;

 	if (info->fbops->fb_sync)
 		info->fbops->fb_sync(info);

 	if (par->fd_size < d_cellsize * len) {
+		kfree(par->fontbuffer);
+		par->fontbuffer = NULL;
+		par->fd_size = 0;
+
 		dst = kmalloc_array(len, d_cellsize, GFP_KERNEL);

 		if (dst == NULL) {
 			err = -ENOMEM;
 			goto finished;
 		}

 		par->fd_size = d_cellsize * len;
-		kfree(par->fontbuffer);
 		par->fontbuffer = dst;
 	}

 	dst = par->fontbuffer;
 	memset(dst, 0, par->fd_size);

 	switch (par->rotate) {
 	case FB_ROTATE_UD:
 		for (i = len; i--; ) {
 			rotate_ud(src, dst, vc->vc_font.width,
 				  vc->vc_font.height);

 			src += s_cellsize;
 			dst += d_cellsize;
 		}
 		break;
 	case FB_ROTATE_CW:
 		for (i = len; i--; ) {
 			rotate_cw(src, dst, vc->vc_font.width,
 				  vc->vc_font.height);
 			src += s_cellsize;
 			dst += d_cellsize;
 		}
 		break;
 	case FB_ROTATE_CCW:
 		for (i = len; i--; ) {
 			rotate_ccw(src, dst, vc->vc_font.width,
 				   vc->vc_font.height);
 			src += s_cellsize;
 			dst += d_cellsize;
 		}
 		break;
 	}

 finished:
 	return err;
 }
